/** One caption cue. Times are in seconds. */
export interface Segment {
  start: number;
  duration: number;
  text: string;
}

/** A caption track that exists for a video. */
export interface TrackInfo {
  languageCode: string;
  name: string;
  /** "asr" = YouTube auto-generated, "manual" = uploaded by the creator. */
  kind: "asr" | "manual";
}

/** What /api/transcript returns on success. */
export interface TranscriptResult {
  videoId: string;
  title: string;
  author: string;
  lengthSeconds?: number;
  thumbnailUrl: string;
  language: string;
  languageName: string;
  isAutoGenerated: boolean;
  tracks: TrackInfo[];
  segments: Segment[];
  /** Which fetcher produced it: "innertube-android" | "watch-page" | "supadata" | "whisper" | "fixture". */
  source: string;
  fetchedAt: string;
}

export type TranscriptErrorCode =
  | "INVALID_ID"
  | "VIDEO_UNAVAILABLE"
  | "NO_CAPTIONS"
  | "LANG_NOT_FOUND"
  | "BLOCKED"
  | "UPSTREAM"
  | "NOT_CONFIGURED";

const STATUS: Record<TranscriptErrorCode, number> = {
  INVALID_ID: 400,
  VIDEO_UNAVAILABLE: 404,
  NO_CAPTIONS: 404,
  LANG_NOT_FOUND: 404,
  BLOCKED: 503,
  UPSTREAM: 502,
  NOT_CONFIGURED: 501,
};

export class TranscriptError extends Error {
  readonly code: TranscriptErrorCode;
  readonly status: number;
  /** Optional: tracks that do exist (for LANG_NOT_FOUND). */
  readonly tracks?: TrackInfo[];
  constructor(code: TranscriptErrorCode, message: string, tracks?: TrackInfo[]) {
    super(message);
    this.name = "TranscriptError";
    this.code = code;
    this.status = STATUS[code];
    this.tracks = tracks;
  }
}
